#!/bin/bash
# HB-Cls scoring (hb_cls_score.py, cais/HarmBench-Llama-2-13b-cls) for the MixAT ladder.
#   DeepInception: the four cells generated by submit_mixat_inference.sh (the undefended
#                  LoRA/FFT DeepInception cells are scored with the controlled grid).
#   ArtPrompt    : all six tokenizer-template cells in results_phase5/artprompt_tokchat/.
# The 13B classifier needs a >= 40 GB GPU. Existing outputs are skipped.
# Required env: PROJECT_ROOT, VENV_DIR
set -euo pipefail
: "${PROJECT_ROOT:?set PROJECT_ROOT}"; : "${VENV_DIR:?set VENV_DIR}"
REPO=$PROJECT_ROOT
VENV=$VENV_DIR
HB=$REPO/toolkits/HarmBench
LOG=$REPO/logs/mixat
SCORED=$HB/results_phase5/scored
mkdir -p "$SCORED" "$LOG"

submit_score() {
  local src=$1 out=$2 tag=$3
  if [ -s "$out" ]; then echo "  already scored: $(basename "$out")"; return 0; fi
  if [ ! -s "$src" ]; then echo "  SKIP (no completions): $src"; return 0; fi
  jid=$(sbatch --parsable --account=YOUR_ACCOUNT --partition=a100-40gb,a100-80gb --qos=standby \
    --gres=gpu:1 --cpus-per-task=6 --mem=48G --time=00:40:00 \
    --job-name="mixat_hbcls_${tag}" --output="$LOG/hbcls_${tag}_%j.log" \
    --wrap="export PYTHONNOUSERSITE=1 && cd $REPO && \
$VENV/bin/python -u $REPO/evaluation/seed42_grid/hb_cls_score.py --completions '$src' --out '$out'")
  echo "submitted HB-Cls ${tag}: $jid"
}

for cell in llama31_base llama31_mixat_base llama31_mixat_lora llama31_mixat_fft; do
  submit_score "$HB/results_phase5/deepinception/${cell}_jbb.jsonl" "$SCORED/${cell}_jbb_hbcls.jsonl" "${cell}_di"
done
for cell in llama31_base llama31_mixat_base llama31_lora llama31_mixat_lora llama31_fft llama31_mixat_fft; do
  submit_score "$HB/results_phase5/artprompt_tokchat/${cell}_jbb.jsonl" \
               "$SCORED/${cell}_jbb_artprompt_tokchat_hbcls.jsonl" "${cell}_ap"
done
